const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const n = Number(data[0]);
const k = Number(data[1]);

let sum = 0;
let answer = 0;
const freq = new Map();
freq.set(0, 1);

for (let i = 2; i < 2 + n; i++) {
    sum += Number(data[i]);
    const need = sum - k;
    const count = freq.get(need);
    if (count !== undefined) {
        answer += count;
    }
    freq.set(sum, (freq.get(sum) || 0) + 1);
}

console.log(answer);
